  "亚运会、世博会带来客流高峰，疫情与灾害使出行减少；每个阶段都有本城目标与阶段总结。": "The Asian Games and World Expos bring ridership peaks, while epidemics and disasters reduce travel; every phase has city goals and a phase summary.",
