  "沿车流方向修线，把开车的人吸引到地铁。": "Build along the traffic direction to win drivers over to the metro.",
  "进阶 {a} / {b} · 可跳过": "Advanced {a} / {b} · optional",
  "进阶：找出拥堵片区": "Advanced: find congested districts",
  "打开「道路拥堵」图层，点击红色道路旁的片区。右侧会告诉你该在哪设站、往哪修线。": "Open the Road Congestion layer and click a district beside a red road. The panel shows where to add stations and which way to build.",
  "更多做法：菜单 → 新手指南。": "More tips: Menu → Player Guide.",
  "进阶：设施接驳": "Advanced: facility access",
  "打开「设施出行需求」图层，点击火车站或医院。「乘地铁比例」就是接驳比例，下方会告诉你怎么提高。": "Open the Facility Demand layer and click the railway station or a hospital. Metro Share is the access share; the panel below shows how to raise it.",
  "进阶：票价": "Advanced: fares",
  "点顶栏「资金」→「票价」，调起步价或每段加价，点「应用新票价」。票价越高，乘客越少。": "Click Funds → Fare, adjust the base fare or per-section charge, then click Apply New Fares. Higher fares mean fewer riders.",
  "添加转弯点（平滑线形中为控制柄）": "Add a bend (a curve handle in Smooth alignment)",
  "共线区段是同一条轨道，只建一次、只收一次费用，两条线路的列车都在这里运行和停靠；在共线轨道上插站时，共用这段轨道的线路一起停靠；调整转弯点或建设方式时，共用的线路同步改变。": "A shared section is one physical track: built and charged once, used and served by trains of every sharing line. A station inserted on it is served by all sharing lines; moving bends or changing the construction type updates all of them together.",
