  "依次收起图层面板、搜索、右侧详情面板与图层；都收起后暂停并展开菜单，再次按下收起菜单并保持暂停。弹窗、输入框优先返回或取消": "Closes, in order, the layer panel, search, the right-hand detail panel and the active layer; once everything is closed it pauses and opens the menu, and pressing it again closes the menu and stays paused. Dialogs and text boxes go back or cancel first",
