  "含风景区环境保护费约 {m}（景区内轨道 {k} 按单价的 {p}，景区站按车站造价的 {q}）": "Includes a scenic-area environmental fee of about {m} ({k} of scenic-area track at {p} of the unit price; scenic-area station at {q} of the station cost)",
  "含风景区环境保护费约 {m}（景区内轨道 {k} 按单价的 {p}）": "Includes a scenic-area environmental fee of about {m} ({k} of scenic-area track at {p} of the unit price)",
  "含风景区环境保护费约 {m}（景区站按车站造价的 {q}）": "Includes a scenic-area environmental fee of about {m} (scenic-area station at {q} of the station cost)",
