  "{p}住了这么多人，最近的地铁站还要走二十多分钟，什么时候能修到我们这儿？": "So many people live in {p}, yet the nearest station is a 20-minute walk. When will the metro reach us?",
  "每天从{p}出门先挤公交再换地铁，单程一个多小时。": "Every day from {p} it's a crowded bus and then the metro: over an hour each way.",
  "{p}这边连个地铁站都没有，下雨天出门太难了。": "There isn't a single metro station around {p}. Going out in the rain is a nightmare.",
  "我家附近终于有地铁了！{s}站开通，出门走几分钟就到。": "Finally a metro near home! {s} station is open, just a few minutes' walk.",
  "{s}站开通后上班少走好远，早上能多睡二十分钟。": "With {s} station open my commute is much shorter. Twenty more minutes of sleep!",
  "第一次从{s}站坐地铁，车站很新，人也不多。": "First ride from {s} station. Brand new and not crowded.",
  "在{s}换乘到{t}要出站走 {m} 米再进站，太绕了。": "Changing from {s} to {t} means leaving the station and walking {m} m. Such a detour.",
  "{s}和{t}要是能在一个站里换乘就好了，现在要走 {m} 米。": "If only {s} and {t} were one station. Right now it's a {m} m walk.",
  "在{s}站换乘要上下好几层，每次多走两三分钟。": "Changing at {s} means going up and down several levels: two or three extra minutes every time.",
  "{s}站换乘的楼梯太长了，提着东西很累。": "The transfer stairs at {s} are so long. Exhausting with bags.",
  "早高峰{s}站排队进站排到了出口外面。": "At rush hour the queue at {s} station reaches outside the entrance.",
  "{s}站早上人太多了，闸机前挤成一团。": "{s} station is packed in the morning. Total crush at the gates.",
  "{l}早高峰太挤了，在{s}站等了两趟才挤上去。": "{l} is so crowded at rush hour. I waited for two trains at {s} before squeezing on.",
  "{l}从{s}到{t}这段车厢里转身都难，能不能加车？": "Between {s} and {t} on {l} you can't even turn around. More trains, please?",
  "{l}准点又快，从{s}坐到{t}很省心。": "{l} is fast and on time. {s} to {t} is so easy.",
  "每天坐{l}通勤，比以前开车稳定多了。": "Commuting on {l} every day is far more reliable than driving was.",
  "票价有点贵，每天来回要 {f}。": "Fares are a bit steep: {f} a day for the round trip.",
  "地铁是方便，可每月光车费就要不少钱。": "The metro is convenient, but the monthly fares really add up.",
  "{r}早高峰堵得动不了，要是有地铁就好了。": "{r} is gridlocked at rush hour. If only there were a metro.",
  "每天在{r}上堵半小时，羡慕住在地铁边的同事。": "Half an hour stuck on {r} every day. Jealous of colleagues who live near the metro.",
  "{r}最近好像没那么堵了，地铁分走了不少人。": "{r} seems less jammed lately. The metro has taken a lot of people off it.",
  "去{x}还得打车或转好几趟公交，附近没有地铁站。": "Getting to {x} still means a taxi or several buses. No station nearby.",
  "{x}离最近的地铁站太远了，希望能修过去。": "{x} is too far from the nearest station. Hope the metro gets there.",
  "新线开通后，地铁出行多了 {d}，身边越来越多人改坐地铁。": "Since the new line opened, metro travel is up {d}. More and more people I know take the metro.",
  "新线开通以后上班终于不用堵在路上了。": "Since the new line opened I'm finally not stuck in traffic on the way to work.",
