  "在这里还能换乘 {lines}，方便多了。": "You can change to {lines} here too. So much easier.",
  "终于不用再转两趟公交了！": "No more changing buses twice!",
  "{m} 米大约要走 {min} 分钟，加上进出闸机更久。": "{m} m is about a {min}-minute walk, longer with the fare gates.",
  "同感，{s}和{t}要是能同站换乘就好了。": "Same here. A same-station transfer between {s} and {t} would be great.",
  "两站之间步行约 {min} 分钟，每天约 {xf}人次在这里换乘，已转交规划研究同站换乘。": "The walk between the stations is about {min} minutes and about {xf} transfers happen here daily. We've asked planning to study a same-station transfer.",
