  "{s}站高峰小时进出站约 {peak} 人次，设计容量 {cap}，负荷 {pct}。": "{s} handles about {peak} entries and exits in the peak hour against a design capacity of {cap}: {pct} load.",
  "建议把{s}站扩建成大型站。": "Suggest expanding {s} into a large station.",
  "我现在都提前二十分钟出门。": "I leave twenty minutes earlier now.",
  "高峰时段已加派站务疏导客流；车站扩建与列车加长正在评估。": "We've added staff to manage crowds at peak times. Station expansion and longer trains are being evaluated.",
