  "拓展": "Extra",
  "合计：财政收入 = 拨款 + 票款 + 车站商业 + 奖励（借款不计入）；支出 = 建设 + 运营": " totals: revenue = grants + fares + station commerce + rewards (loans excluded); spending = construction + operations",
  "；偿债 = 利息 + 本金 + 逾期费用": "; debt service = interest + principal + overdue fees",
  "高客流车站的广告、商铺与上盖物业收入；在车站详情或地图快捷按钮中开发": "Advertising, shop and above-station property income at busy stations; develop from station details or the map quick buttons",
  "在车站详情或地图快捷按钮中开发": "Develop from station details or the map quick buttons",
  "已开发车站": "Developed stations",
  "广告 {a} · 商业街 {b} · 站城一体 {c}": "Ads {a} · arcades {b} · integrated {c}",
  "近一年营运收入中的商业占比": "Commerce share of operating income (past year)",
  "（票款 + 商业）覆盖运营费用 {p}": "(fares + commerce) cover {p} of operating costs",
  "尚无运营费用": "No operating costs yet",
  "票款与车站商业收入": "Fare and station commerce income",
  "合计；两者合计越接近运营费用，越不依赖拨款": "total; the closer the two together get to operating costs, the less you rely on grants",
  "车站商业": "Station Commerce",
  "商业收入最高的车站": "Top stations by commerce income",
  "每月估算（按周平均客流）；换乘站收入 ×{k}": "Monthly estimate (weekly-average ridership); interchanges earn ×{k}",
  "每月收入": "Monthly income",
  "开发等级": "Level",
  "日客流": "Daily riders",
  "还没有开发商业空间的车站。高客流车站可以在车站详情或地图快捷按钮中开发。": "No stations have commercial space yet. Develop busy stations from station details or the map quick buttons.",
  "车站商业月收入": "Station commerce per month",
  "按当前客流估算": "Estimated from current ridership",
  "地铁从客村一带跨过珠江，与番禺市桥直接连通。": "The metro crosses the Pearl River from around Kecun and connects directly to Shiqiao in Panyu.",
  "北站与蒙帕纳斯之间可乘地铁直达，线路穿越塞纳河南北贯穿。": "Gare du Nord and Montparnasse are connected by metro, with the line crossing the Seine north to south.",
  "大轴线": "The Grand Axis",
  "星形广场成为三线交汇的枢纽，并与拉德芳斯直接连通。": "Étoile becomes a three-line interchange with a direct link to La Défense.",
  "静安寺与陆家嘴之间开通过江地铁。": "A cross-river metro opens between Jing'an Temple and Lujiazui.",
  "地铁改变城市": "The metro shapes the city",
  "地铁反过来塑造城市：车站开通后周边居民几年内逐步少开车，沿线道路慢慢缓解；线网越成熟，新增人口和岗位越多地向车站与换乘枢纽聚集。拥堵图层新增「拥堵变化」，城市发展图层新增「地铁带动」。": "The metro now shapes the city: residents near new stations drive less over a few years and roads along the line gradually ease, and the more mature the network, the more new residents and jobs gather around stations and interchanges. The congestion layer adds Change and the city growth layer adds Metro pull.",
  "「地铁圈」上线：点右下角满意度打开乘客动态，帖子附随手涂鸦和评论区回复，还能关注市民、跟进同一片区的变化；居民满意度详情也并入其中。": "Meet Metro Circle: tap satisfaction at bottom right to open the rider feed, with doodles, reply threads and citizens you can follow to track how their neighbourhood changes; satisfaction details now live there too.",
  "高客流车站可开发广告、商业街与站城一体，增加收入并带动周边发展，还能装修车站；财政统计新增车站商业图表，后期经营更可持续。": "Busy stations can add advertising, shopping arcades and integrated development for extra income and nearby growth, and stations can be redecorated; finance statistics add station commerce charts, making late-game budgets more sustainable.",
  "画线更顺手：拖动时实时显示最终弧线，冲突直接标出问题轨道段并给出调整方向和幅度，可一键修正；连续绘线少切换工具，2D与2.5D反馈一致。": "Smoother drawing: the final curve shows live while dragging, conflicts highlight the exact problem section with the direction and distance to fix it and a one-click fix, continuous drawing needs fewer tool switches, and 2D and 2.5D give the same feedback.",
  "新手教程重新设计：约10分钟走完一轮规划、建设与反馈，引导更清楚；建设效果报告加入归因，八座城市加入16项规划难题与可选挑战。": "A redesigned tutorial takes about 10 minutes for a full planning, construction and feedback cycle. Impact reports explain the results, and eight cities offer 16 local planning challenges alongside optional objectives.",
  "大型线网改线、视图切换、载入和跳月明显更快；修复进出主菜单闪烁、按钮悬停抖动，满意度与暂停提示不再随右侧详情移动。": "Editing large networks, switching views, loading and skipping months are much faster; fixed the main-menu flash and button jitter on hover, and the satisfaction and pause indicators no longer move when the side panel opens.",
  "新任务：{t}": "New task: {t}",
  "{d}：新任务：{t}": "{d}: New task: {t}",
  "参考 {l}（{y} 年开通）": "Reference: {l} (opened {y})",
  "在 2.5D 近景显示站台、出入口与车站装修": "Show platforms, entrances and station decoration in close-up 2.5D views",
  "经营与任务规则已更新，旧票制、线网及历史账目保留": "Financial and task rules updated; previous fares, network and accounts are preserved",
  "保留原票制、站线、资金、债务、任务与已结算历史；更新后的规则只影响未来经营与任务评估，升级当月提供任务与满意度保护。": "Existing fares, network, funds, debt, tasks and settled history are preserved. Updated rules affect future operations and task assessment, with task and satisfaction protection during the upgrade month.",
  "存档数据未能在当前版本中恢复。": "This save could not be restored in the current version.",
