  "城市中隐藏全部界面，只看画面": "Hide the whole interface in the city and just watch",
  "经纬网格 · 建站与绘线时可吸附": "Grid · stations and lines can snap to it",
  "长期负余额、低于负债下限或满意度长期过低会导致挑战失败。": "Long negative balances, falling below the debt limit or prolonged low satisfaction end the challenge.",
