  "高峰运力不足：还差约 {v0} 列。智能调度只调度已有列车，可以购买列车，或从客流较少的线路调车。": "Peak capacity is short by about {v0} trains. Smart dispatch only uses trains you own: buy more, or move trains from quieter lines.",
  "{v0} 列列车编组超过本线站台长度，不能上线：升级沿线车站，或调往其他线路、出售。": "{v0} trains are too long for this line's platforms and cannot run. Upgrade stations along the line, or move or sell them.",
