  "智能调度已用上全部配属列车，高峰还差约 {v0} 列，车厢会更拥挤、候车更久。可以购买列车，或从客流较少的线路调车。": "Smart dispatch is using every assigned train and is still about {v0} short at peak, so trains will be more crowded and waits longer. Buy trains or move some from quieter lines.",
