  "投入的列车数决定发车频率（最小间隔 2 分钟）：在「列车运营」分页购买、调配列车或改为手动设定；满载时也可以升级车站、换长编组列车，或修平行线分流。": "Trains in service set the frequency, with headways of at least 2 minutes. Use the Train Operations tab to buy, move or manually schedule trains. When trains are full, you can also upgrade stations, run longer trains or build a parallel line.",
