  "退出合同？": "Withdraw from the contract?",
  "保证金不予退还，未来 {v0} 个月拨款 ×{v1}，满意度与履约信誉下降。已建的线路照常归公司运营。": "The bid bond is forfeited, grants are ×{v1} for the next {v0} months, and satisfaction and your rating fall. Lines already built stay in service.",
  "已结束": "Ended",
  "{v0} 项": "{v0} items",
  "期满移交": "Hand over at term",
  "违约": "Default",
  "未中标": "Not won",
  "累计收到": "received in total",
  "简化模型说明": "About the Simplified Model",
  "{v0}；不同国家与年代的真实制度差别很大，游戏统一用一套简化规则，不代表任何真实合同。": "{v0}. Real systems vary widely by country and era; the game uses one simplified set of rules and does not represent any real contract.",
  "普通政府任务仍是任务；只有含投资、风险分担与长期履约的项目才作为合同招标。可以投标、放弃，或不接合同、自主建设。": "Ordinary government tasks remain tasks. Only projects with investment, shared risk and long-term obligations are tendered as contracts. You can bid, pass, or build on your own.",
  "中标后公司出资建设：按期开通收建设补助、退保证金；运营期每月考核服务连通与拥挤，未达标按比例扣减可用性付费。": "After winning, the company funds construction. Opening on time earns the subsidy and returns the bond. During operation, service and crowding are reviewed monthly, and availability payments are cut if targets are missed.",
  "新线合同按政府预测分担客流风险：低于保底线由政府补差，高于分成线要上交一部分。铁路＋物业合同的物业收益随客流与经济周期波动，可能亏损。": "New-line contracts share ridership risk against the government forecast: below the guarantee line the government covers part of the shortfall, and above the sharing line the company hands over part of the excess. Rail + property income moves with ridership and the economy and can make a loss.",
  "到期未开通、服务连续 3 个月中断或主动退出即违约：保证金不退（运营期另付违约金），拨款 ×{v0}（{v1} 个月），满意度与信誉下降。": "Missing the opening deadline, 3 months of interrupted service or withdrawing counts as a default: the bond is forfeited (a penalty is paid during operation), grants are ×{v0} for {v1} months, and satisfaction and your rating fall.",
  "地铁公司开始承接政府合同": "The metro company can now take government contracts",
  "政府开始以招标方式提出建设需求（{v0}，游戏采用简化模型）。可以投标、放弃，或不接合同、自主建设；按期完成并通过考核会获得补助与长期付费，违约会扣减拨款。": "The government now tenders projects ({v0}; the game uses a simplified model). Bid, pass, or build on your own. Finishing on time and passing reviews brings subsidies and long-term payments; defaults reduce grants.",
