  "本月车站商业运营与维护成本": "Station commerce operation and upkeep this month",
  "车站客流越大，广告与商铺租金越多{v0}。日客流约 {v1} 人次。开发后每年有运营与维护成本，客流太少会亏损；商业街与站城一体的收入随经济周期涨落。": "More riders bring more advertising and shop rental income{v0}. Daily ridership: about {v1}. Developments have yearly operating and upkeep costs, so quiet stations lose money, and shopping streets and integrated developments rise and fall with the economy.",
