  "单程": "One way",
  "南岸的人每天过江去老城上班。先用一条地铁连起两岸，再学怎么管理线路、扩大线网和经营，全程约 12 分钟。": "People on the south bank cross the river to work in the old town every day. First link the banks with a metro line, then learn to manage lines, grow the network and run the finances. About 12 minutes in all.",
  "发车间隔由投入的列车决定：列车越多越密，运营费也越高。智能调度只用已有的列车。": "Headways depend on the trains in service: more trains run more often and cost more. Smart dispatch only uses trains you own.",
  "发车频率与编组都到上限：需要分流，例如修平行线路或加开交路": "Frequency and train length are at their limits: spread the load with a parallel line or an extra service",
  "取消这个交路，列车回到全程交路": "Cancel this service; its trains return to the full route",
  "只停换乘站": "Interchanges only",
  "只改运营组织，不收费、立即生效；交路在配属列车后开行。": "Operations only: free and immediate. A service runs once trains are assigned.",
  "只有绘线和建站要回到地图。": "Only drawing lines and placing stations happen on the map.",
  "可以": "Suggested:",
  "同一条轨道上早高峰合计约 ": "Morning-peak total on the same track about ",
  "同一页还能设运行速度（越慢允许的弯越急）和加开快车、区间车，让运力集中到客流大的地方。": "This page also sets running speed (slower lines can take tighter curves) and extra express or short-turn services to focus capacity where it is needed.",
  "周转": "Round trip",
  "回地图查看": "View on map",
  "在「票价」里调好后点「应用新票价」。青湾资金不限，真实城市选「经营挑战」要自己平衡收支。": "Set fares under Fares, then press Apply. Qingwan has unlimited funds; in a real city's Challenge mode you balance the books yourself.",
  "在入口上方出现小卡片，最多每 3 个月一次；关闭后只显示角标": "A small card appears above the entry, at most once every 3 months. When off, only the badge shows",
  "在地图上定位这座车站": "Locate this station on the map",
