  "快车（跳站）": "Express (skip-stop)",
  "所有线路、车站和列车都在这里管理：改名改色、配车、定站台规模、做商业开发和装修。": "Every line, station and train is managed here: rename and recolour, assign trains, set platform size, develop shops and redecorate.",
