  "读懂城市": "Read the City",
  "调入闲置列车 ": "Bring in idle trains: ",
  "购买列车 ": "Buy trains: ",
  "贯通、拆开、支线与区段调整": "Through-running, splitting, branches and section changes",
  "资金不足：需要约 ": "Not enough funds: about ",
  "起讫站必须停靠": "Terminals must be stops",
  "跟着发光的气泡操作；右上角目录可以回看，每一步都能跳过。": "Follow the glowing bubble. The list at the top right lets you review, and every step can be skipped.",
  "车站 · 约 ": "station · about ",
  "车站名称": "Station name",
  "车站建在住宅最密的地方，走路就能到。放下前，光标旁会显示站名。": "Place stations where housing is densest so people can walk there. The name appears next to the cursor before you place it.",
  "地铁芯": "MetroCore",
  "地铁芯：线路、车站与列车管理": "MetroCore: manage lines, stations and trains",
  "运行交路 ": "Services ",
  "运行交路：快车跳过的车站不停车，节省时间但服务变少；区间车集中运力在客流大的一段。各交路分别配车，同一条轨道合计最多 ": "Services: express trains skip stations, saving time but serving fewer stops; short-turn trains focus capacity on the busiest stretch. Each service has its own trains, with at most ",
  "运行速度": "Running speed",
  "运行速度：最小转弯半径 ": "Running speed: minimum curve radius ",
  "运行速度：速度越低，允许的转弯半径越小（40 km/h 约 100 m，120 km/h 约 600 m）；高于 80 km/h 的线路要用足够快的车型，运营费用也更高。": "Running speed: slower lines can take tighter curves (about 100 m at 40 km/h, 600 m at 120 km/h). Lines over 80 km/h need fast enough trains and cost more to run.",
  "这样设置与全程站站停相同：请缩短区间或选择要通过的车站。": "This is the same as the all-stops service: shorten the section or choose stations to pass.",
  "选「车站客流」": "Choose Station Flow",
  "选学": "Optional",
  "选学 ": "Optional ",
  "通过 ": "Passes ",
  "配属 / 高峰需要": "Assigned / peak need",
  "隔站停靠": "Every other stop",
  "需要关注": "Needs attention",
  "高峰满载": "Peak load",
  "高峰需要 ": "Peak need ",
  "高速线路附加（": "High-speed surcharge (",
  "默认全程站站停": "All-stops by default",
  "（资金不足）": "(not enough funds)",
  "，约 ": ", about ",
  "，轨道造价附加 ": ", track cost surcharge ",
  "：转弯半径约 ": ": curve radius about ",
  "；本线最急处约 ": "; tightest curve on this line about ",
  "；需要最高速度不低于 ": "; needs a train with a top speed of at least ",
  "共 ": "",
  " 月": " ",
  "三档报价": "Three bid levels",
  "三档报价越便宜越容易中标，风险也越大；履约信誉影响中标率和每月拨款。在任务页的「合同」分页投标。": "Cheaper bids are likelier to win but carry more risk. Contract reputation affects win chance and monthly grants. Bid under the Contracts tab on the Tasks page.",
  "上一年财政好，今年拨款的财力系数就高（×0.70–1.30）；衰退时车站商业收入也会下降。": "A good fiscal year raises this year's grant capacity factor (×0.70–1.30); in a downturn station commerce earns less too.",
  "中标建设": "Win and build",
  "信誉上升": "Reputation up",
  "借来的钱进入「建设专项资金」，只能修地铁和买车，不能付运营费或利息。": "Borrowed money goes into the Construction Fund: it can only pay for building and trains, not operating costs or interest.",
  "列车、车站规模和商业开发都在右下角的「地铁芯」；投标在任务页的「合同」分页。": "Trains, station size and commerce are all in MetroCore at the bottom right. Bid under the Contracts tab on the Tasks page.",
  "列车也是一笔账": "Trains Are a Budget Line Too",
  "列车按车型整列购买，买车计入建设支出；不用的列车可以调到别的线，或按残值出售。": "Trains are bought whole by model and count as construction spending. Spare trains can move to other lines or be sold at residual value.",
  "可以投标、放弃或自己建：中标先交保证金，自己出资建设，按期完工收补助并退保证金。": "You can bid, pass or build on your own. Winning takes a deposit; you fund the build, and on-time completion earns a subsidy and the deposit back.",
  "商业 · 合同": "Commerce · Contracts",
  "地铁芯 · 线网管理": "MetroCore · Network management",
  "大客流的换乘站回本最快，也会吸引周边的人口与岗位。": "Busy interchanges pay back fastest and also attract residents and jobs nearby.",
  "太少会亏：有维护成本": "Too few riders loses money: upkeep costs",
  "客流够大才赚钱": "Profitable only with enough riders",
  "广告便利店": "Ads and kiosks",
  "建设与拆迁：确认建设时一次付清；新线随线配车的费用也算在里面。": "Construction and demolition: paid in full on confirmation, including trains that come with a new line.",
  "开局满 3 年、线网超过 12 km，并到了本城开放合同的年份后，政府开始招标：新线、铁路＋物业和扩容改造。": "Three years in, with over 12 km of network and once the city's contract year arrives, the government starts tenders: new lines, rail plus property and capacity upgrades.",
  "投标": "Bid",
  "拨款 = 基础额度 × 财力 × 满意度 × 任务 × 履约信誉。": "Grant = base amount × fiscal capacity × satisfaction × tasks × contract reputation.",
  "按期开通": "Open on time",
  "接入运营的车站可以逐级开发：广告与便利店、站内商业街、站城一体。": "Operating stations can be developed in stages: ads and kiosks, a shopping street, then station-city integration.",
  "收入随客流和经济周期涨落；开发后每年有运营与维护成本，客流太少会亏损。": "Income follows ridership and the economic cycle. Developed stations have yearly running and upkeep costs and can lose money with too few riders.",
  "政府合同": "Government contracts",
  "政府合同（PPP）": "Government Contracts (PPP)",
  "政府拨款：每月初发一次，开局时是最大的一笔。": "Government grant: paid at the start of each month, the largest source early on.",
  "整列购买": "Buy whole trains",
  "残值出售": "Sell at residual value",
  "满意度系数 = 0.6 + 0.8 × 满意度 ÷ 100；几项任务同时打折时，任务系数最低 ×0.7；政府合同开放后才计履约信誉（×0.95–1.05）。": "Satisfaction factor = 0.6 + 0.8 × satisfaction ÷ 100. Several task penalties together bottom out at ×0.7. Contract reputation (×0.95–1.05) applies once contracts open.",
  "点顶栏「资金」打开「财政与经济」：票价在「财政」页，发债在「融资」页。": "Click Funds in the top bar to open Finance and Economy: fares are on the Finance page, bonds on the Financing page.",
  "画质": "Graphics quality",
  "站城一体": "Station-city",
  "线网运行平稳": "Network running smoothly",
