  "水系 · {v0}": "Waterways · {v0}",
  "{v0}：受相邻区段「{v1}」影响，转弯半径降至约 {v2} m（最小 {v3} m）": "{v0}: The adjacent section {v1} tightens this curve to about {v2} m (minimum {v3} m)",
  "已获得 · ": "Unlocked · ",
  "未获得 · ": "Locked · ",
  "查看、改名、导入或导出全部城市的进度与存档": "View, rename, import or export games and saves for every city",
  "本市车型 · {v0}": "Local model · {v0}",
  "通用车型 · {v0}": "Generic model · {v0}",
  "还有 1 年": "next year",
  "地铁公司：合同、列车与地铁芯": "The metro company: contracts, trains and MetroCore",
  "经营挑战中，你经营的是一家地铁公司：线网成形后，政府招标提出新线 PPP、铁路＋物业、扩容改造三类项目，可以投标、放弃或自主建设。中标后自己设计、出资建设，按期开通收补助，运营期每月考核服务与拥挤；违约则保证金不退、拨款打九折、信誉下降。任务页「合同」用图表展示招标和履约，地图同步标出片区与走向。": "In Challenge mode you now run a metro company. Once your network takes shape, the government tenders three kinds of project (new-line PPP, rail + property and capacity upgrade): bid, pass, or build on your own. After winning, you design and fund the project; opening on time earns a subsidy, and service and crowding are reviewed monthly during operation. A default forfeits the bond, cuts grants by 10% and lowers your rating. The Contracts tab charts tenders and performance, and the map marks each area and route.",
  "车站商业不再稳赚：开发后每年有运营与维护成本，客流太少的车站会亏损，收入随经济周期涨落；铁路＋物业项目客流低迷时同样会亏。": "Station commerce is no longer a sure thing: developments have yearly operating and upkeep costs, quiet stations lose money, and income rises and falls with the economy. Rail + property projects can lose money too when ridership is weak.",
  "新增列车采购：按车型与编组整列购买、配属到线路，投入多少列决定发车频率；四十多款真实与通用车型按城市与年代开放。线路详情新增「列车运营」：智能调度只用已有列车，运力不足时提醒买车，也可按时段手动设定；线路可设运行速度、加开快车和区间车。运营按车厢公里计费，旧车按残值出售。": "Train procurement: buy whole trains by model and length and assign them to lines; the trains in service set the frequency, and more than forty real and generic models open by city and era. Line details add Train Operations: smart dispatch uses only the trains you own and reminds you to buy more when short, or set trains by time of day; lines can also set running speeds and add express or short-turn services. Operation is charged per car-kilometre, and old trains sell at residual value.",
  "新增「地铁芯」线网管理系统：线路与车站都有表格、趋势图和地图预览，改造建筑风格、商业开发时能先试看，改造前后的指标可以对比。": "New MetroCore network management system: lines and stations have tables, trend charts and map previews; you can try out architectural styles and commercial development before committing, and compare the figures before and after each upgrade.",
  "车站客流越大，广告与商铺租金越多。日客流约 {v0} 人次。开发后每年有运营与维护成本，客流太少会亏损；商业街与站城一体的收入随经济周期涨落。": "More riders bring more advertising and shop rental income. Daily ridership: about {v0}. Developments have yearly operating and upkeep costs, so quiet stations lose money, and shopping streets and integrated developments rise and fall with the economy.",
  "暂无招标。政府约每 {v0} 个月按城市需要提出一个项目（下次约 {v1}）；不接合同也可以自主建设。": "No open tenders. The government proposes a project about every {v0} months as the city needs it (next around {v1}). You can always build on your own without a contract.",
  "暂无招标。政府约每 {v0} 个月按城市需要提出一个项目；不接合同也可以自主建设。": "No open tenders. The government proposes a project about every {v0} months as the city needs it. You can always build on your own without a contract.",
  "「{v0}」新线 PPP 项目": "{v0} New-Line PPP Project",
  "「{v0}」铁路＋物业项目": "{v0} Rail + Property Project",
  "{v0}约 {v1} 人口与岗位，还没有地铁。政府招标：公司投资建设连到「{v2}」一带的线路（约 {v3} km），并运营 {v4} 年。补助较少，换取片区的物业开发权：收益随客流与经济周期波动，经营不善会亏损。": "{v0} has about {v1} residents and jobs but no metro. The government invites bids: the company funds a line of about {v3} km to the {v2} area and runs it for {v4} years. A smaller subsidy comes with property development rights in the area; that income moves with ridership and the economy, and poor management can lose money.",
  "客流低于预测 {v0}%：政府补差额的 {v1}%；高于 {v2}%：超出部分交 {v3}%": "Below {v0}% of forecast, the government covers {v1}% of the shortfall; above {v2}%, the company hands over {v3}% of the excess",
  "无客流保底；高于 {v0}%：超出部分交 {v1}%": "No ridership guarantee; above {v0}%, the company hands over {v1}% of the excess",
  "政府支付 / 物业净收益": "Government payments / net property income",
  "以「{v0}」中标。{v1} 前完成建设（连通「{v2}」与「{v3}」），已付履约保证金 {v4}。": "Won with the {v0}. Connect {v2} and {v3} by {v1}. Bid bond of {v4} paid.",
  "以「{v0}」中标。{v1} 前完成建设（连通「{v2}」与「{v3}」），已付履约保证金 {v4}、地价 {v5}。": "Won with the {v0}. Connect {v2} and {v3} by {v1}. Bid bond of {v4} and land premium of {v5} paid.",
  "以「{v0}」中标。{v1} 前完成建设（全线 8 节编组），已付履约保证金 {v2}。": "Won with the {v0}. Run 8-car trains on the whole line by {v1}. Bid bond of {v2} paid.",
  "提前 {v0} 个月完成建设，收到建设补助 {v1}，进入 {v2} 年运营期：每月按服务考核收取可用性付费。": "Finished {v0} months early. Subsidy of {v1} received; the {v2}-year operating period begins, with monthly availability payments by performance.",
  "按期完成建设，收到建设补助 {v0}，进入 {v1} 年运营期：每月按服务考核收取可用性付费。": "Finished on time. Subsidy of {v0} received; the {v1}-year operating period begins, with monthly availability payments by performance.",
  "{v0}。履约保证金不予退还，未来 {v1} 个月拨款 ×{v2}，履约信誉下降。": "{v0}. The bid bond is forfeited, grants are ×{v2} for {v1} months, and your contract rating falls.",
  "{v0}。支付违约金，未来 {v1} 个月拨款 ×{v2}，履约信誉下降。": "{v0}. A default penalty is paid, grants are ×{v2} for {v1} months, and your contract rating falls.",
  "同时履约的合同最多 {v0} 个": "At most {v0} contracts can be active at once",
  "一般资金不足以支付履约保证金（{v0}）": "Not enough general funds for the bid bond ({v0})",
  "一般资金不足以支付履约保证金与地价（{v0}）": "Not enough general funds for the bid bond and land premium ({v0})",
  "{v0} · 每月净收 {v1}": "{v0} · net {v1} per month",
  "{v0} · 每月净亏 {v1}": "{v0} · loses {v1} per month",
  "{v0} 站 · 每月净收 {v1}": "{v0} stations · net {v1} per month",
