  "10 列胶轮车（MP 59、MP 89 或 MP 14）在线运营。": "10 rubber-tyred trains (MP 59, MP 89 or MP 14) in service.",
  "1900 年 7 月前让世界博览会通地铁（巴黎 1 号线的通车时间，史实）。": "Serve the World's Fair by metro before July 1900 (when Paris Line 1 opened).",
  "1964 年 10 月奥运会开幕前，国立竞技场、日本武道馆与羽田机场都通地铁，并彼此连通。": "Before the Olympics in October 1964, connect the National Stadium, Nippon Budokan and Haneda Airport by metro.",
  "1979 年 10 月前开通观塘至石硖尾的地铁（史实通车时间）。": "Open a metro from Kwun Tong to Shek Kip Mei before October 1979 (the historical opening date).",
  "1996 年 3 月前开通 8 km 以上的线路（台北捷运首条路线的通车时间，史实）。": "Open a line of at least 8 km before March 1996 (when Taipei's first metro line opened).",
  "2004 年 9 月前建成 8 km 以上的高架线路（武汉首条轨道交通 2004 年通车，史实）。": "Build at least 8 km of elevated line before September 2004 (Wuhan's first line opened in 2004).",
  "2008 年 8 月奥运会开幕前，国家体育场与北京南站都通地铁，并彼此连通。": "Before the Olympics in August 2008, connect the National Stadium and Beijing South by metro.",
  "2010 年 11 月亚运会开幕前，天河体育中心、广东奥体中心与花城广场都通地铁，并彼此连通。": "Before the Asian Games in November 2010, connect Tianhe Sports Centre, the Guangdong Olympic Centre and Huacheng Square by metro.",
  "2010 年世博会期间（至 10 月），三成五以上的参观者乘地铁前往。": "During Expo 2010 (until October), at least 35% of visitors arrive by metro.",
  "2010 年底前线网达到 400 km（史实 2010 年约 420 km）。": "Reach 400 km of network by the end of 2010 (about 420 km historically).",
  "2016 年 6 月迪士尼开园前，地铁通到川沙的度假区。": "Bring the metro to the Chuansha resort before Disneyland opens in June 2016.",
  "2023 年 9 月亚运会开幕前，杭州奥体中心与杭州西站都通地铁，并彼此连通。": "Before the Asian Games in September 2023, connect Hangzhou Olympic Centre and Hangzhou West by metro.",
  "3 段以上轨道跨越 800 米以上的水面。": "3 or more track sections crossing over 800 m of water.",
  "4 段以上轨道跨越 300 米以上的水面，其中至少 2 段超过 1 km。": "4 or more track sections crossing over 300 m of water, at least 2 of them over 1 km.",
