  "运行速度 100 km/h 以上的线路通到香港国际机场。": "A line of 100 km/h or more reaches Hong Kong International Airport.",
  "运行速度 120 km/h 的线路达到 25 km，并有 5 列以上 16 号线快车型在线。": "A 120 km/h line of at least 25 km, with 5 or more Line 16 express trains in service.",
  "运行速度不高于 60 km/h 的全高架线路达到 8 km，小半径穿过城区。": "A fully elevated line of no more than 60 km/h and at least 8 km, threading tight curves through the city.",
