  "铁路加物业，世界第一的分担率": "Rail plus property, the world's highest metro share",
  "香港迪士尼乐园通地铁，并能乘地铁直达中环。": "Hong Kong Disneyland reached by metro, with a direct ride to Central.",
  "魔都总规划师": "Shanghai Chief Planner",
  "魔都速度": "Shanghai Speed",
  " 项需要关注": " items need attention",
  "任务大多改成复合条件：同一个任务同时考核网络形态、运营结果、成本或发展效果，各城市的要求贴合自己的历史，任务文字写到的要求都会真实判定。到期只完成主体算部分完成，全部完成奖励更高。": "Most tasks now have combined goals, testing network shape, operating results, cost or development together. Each city's requirements fit its own history, and everything a task's text asks for is really checked. Finishing only the core goal by the deadline counts as a partial success, and completing everything pays more.",
  "· 地铁覆盖率提高可吸引更多人口（最多约 +6%）": "· Better metro coverage attracts more residents (up to about +6%)",
  "· 起终点步行接驳时间（沿道路计算）": "· Walking time at both ends of the trip (along roads)",
  "· 地铁对汽车出行的吸引（不按固定比例下降）": "· How well the metro draws car trips (not a fixed percentage drop)",
  "{v0} 站 · 平均站距 {v1} km → 最低 {v2} 列/时；客流需要 {v3} 列/时（按服务水平）": "{v0} stations · average spacing {v1} km → minimum {v2} trains/h; ridership needs {v3} trains/h (at service standard)",
  "每个进度相互独立；自动存档在两个位置轮换写入，手动存档最多 {v0} 个。导入的存档会作为新的存档加入，不会覆盖已有进度。": "Each game is independent. Autosaves alternate between two slots; up to {v0} manual saves. Imported saves are added as new saves and never overwrite existing progress.",
  "已取消导出": "Export cancelled",
  "工作日早高峰，住在该片区的人从家到工作地点的门到门时间（含步行、候车、换乘、停车）。": "Weekday morning peak: door-to-door time from home to work for people living in this area, including walking, waiting, transfers and parking.",
  "工作日早高峰，住在该片区的人从家到工作地点的门到门时间（含步行、候车、换乘、停车）。全市平均 {v0} 分钟。": "Weekday morning peak: door-to-door time from home to work for people living in this area, including walking, waiting, transfers and parking. City average: {v0} min.",
