  "写实轨道，近看有道床、桥面与栏杆": "Realistic track with ballast, bridge decks and parapets up close",
  "浅色系：柔和的线路色带白边，换乘站外圈是各线路的颜色；线路图是浅天蓝点阵底": "A light palette: soft line colours with white edges, and interchanges ringed in the colour of each line; the network map has a pale sky-blue dotted background",
  "细墨线配线路色晕染，换乘站是墨圈里一圈线路色、中心一点朱砂；线路图是宣纸底、楷体站名": "Fine ink lines over a wash of line colour, with interchanges as an ink ring around each line's colour and a vermilion centre; the network map uses rice-paper tones and brush-style station names",
