  "1915 年起大都会铁路用“大都会乡土”宣传沿线的郊区住宅（史实）": "From 1915 the Metropolitan Railway promoted the suburbs along its line as \"Metro-land\" (historical)",
  "1904 年地铁通到阿克斯布里奇（史实）": "The metro reached Uxbridge in 1904 (historical)",
  "1907 年深层地铁通到戈尔德斯格林，田野很快变成住宅区（史实）": "The deep-level tube reached Golders Green in 1907, and the fields soon became housing (historical)",
  "1921 年起建设贝肯特里住宅区，当时世界最大的公共住房区；1931 年福特汽车厂投产（史实）": "Becontree, then the largest council estate in the world, began in 1921; the Ford plant opened in 1931 (historical)",
