  "两次大战之间伦敦的主要机场，1959 年关闭。": "London's main airport between the wars, closed in 1959.",
  "1946 年启用，1977 年皮卡迪利线通到这里（史实背景，本局由你规划）。需求点设在中央航站区。": "Opened in 1946; the Piccadilly line reached it in 1977 (historical background: here the route is yours to plan). The demand point is in the central terminal area.",
  "盖特威克机场在地图南缘以南约 30 km，此处为布莱顿干线方向出图的接驳点。": "Gatwick Airport is about 30 km south of the map edge; this is the link point on the Brighton Main Line.",
  "2007 年 11 月起欧洲之星由滑铁卢改到这里。": "Eurostar moved here from Waterloo in November 2007.",
  "二战后仍很繁忙，集装箱时代到来后一路衰落，1980 年关闭。": "Still busy after the Second World War, it declined once containers arrived and closed in 1980.",
  "一战高峰时雇用近十万人，1967 年关闭。": "Employed nearly 100,000 at its First World War peak; closed in 1967.",
  "1991 年一号广场落成，之后成为欧洲最大的金融商务区之一。": "One Canada Square was completed in 1991, and the area went on to become one of Europe's largest financial districts.",
  "1854 年迁到南伦敦的玻璃巨构，1936 年毁于大火。": "The glass giant moved to south London in 1854 and burned down in 1936.",
  "1908 年奥运会主场，也是英法博览会的场地，1985 年拆除。": "Main venue of the 1908 Olympics and site of the Franco-British Exhibition; demolished in 1985.",
  "1923 年“白马决赛”，1948 年奥运会主场，2007 年重建。": "Home of the 1923 \"White Horse Final\" and the 1948 Olympics; rebuilt in 2007.",
  "2012 年奥运会主场。": "Main venue of the 2012 Olympics.",
  "两年间约 2700 万人次参观，地铁与铁路专门开行接驳列车。": "About 27 million visits over two years, with special trains laid on by the metro and railways.",
  "战后第一场全国庆典，南岸的废墟上建起穹顶馆与皇家节日大厅。": "The first national celebration after the war: the Dome of Discovery and the Royal Festival Hall rose on the ruins of the South Bank.",
