  "还有不少市民步行走不到地铁": "Many residents still cannot walk to the metro",
  "乘地铁的人还不够多，可以加密换乘、提高速度或调整票价": "Too few people ride. Add interchanges, raise speeds or adjust fares",
  "高峰道路还很拥堵，主要走廊值得再加一条线": "Roads are still jammed at peak; main corridors deserve another line",
  "部分线路和车站长期拥挤，可以加车、升级车站或修平行线": "Some lines and stations stay crowded. Add trains, upgrade stations or build parallel lines",
  "市民还不太满意，通勤时间和拥挤是主要原因": "Residents are not yet satisfied, mainly over commute times and crowding",
