  "前海": "Qianhai",
  "2010 年前海规划获批（史实）；新土地先修路，随后才有写字楼和住宅": "Qianhai plan approved in 2010 (historical). Roads come first on the new land, then offices and homes",
  "后海滨路以东的填海土地，后来成为南山的总部基地（史实）": "Reclaimed land east of Houhai Binlu that later became Nanshan's headquarters district (historical)",
