  "1991 年 10 月启用，航站楼在第一跑道东侧（已拆除，位置取现存停机坪，为近似）；2013 年 11 月全部航班迁到 T3。": "Opened in October 1991 with terminals east of the first runway (since demolished; the position follows the surviving apron and is approximate). All flights moved to T3 in November 2013.",
