  "按现在的客流估算，每天约 {v0}": "At current ridership, about {v0} a day",
  "跨境附加费加在车费上，只向进出这个接驳口的乘客收。收得越高，改走其他方式的旅客越多。票价管理的收支页会单独列出这笔收入。": "The cross-border surcharge is added to the fare and only charged to passengers entering or leaving through this crossing. The higher it is, the more travellers choose other ways. The Income & Costs page under Fares lists this income separately.",
  "调整跨境附加费": "Cross-border surcharge changed",
  "{v0}的跨境附加费：{v1}。居民出行选择正在重新计算": "{v0} cross-border surcharge: {v1}. Residents' travel choices are being recalculated",
  "按线路筛选": "Filter by line",
  "勾选车站可以批量调整": "Tick stations to change them together",
  "已选 {v0} 座车站": "{v0} stations selected",
  "全选当前 {v0} 座": "Select all {v0}",
  "选择{v0}": "Select {v0}",
  "小型": "Small",
