  "；涨幅明显高于物价，满意度下降 ": "; the rise far exceeds inflation: satisfaction falls by ",
  " 分，持续 6 个月": " points for 6 months",
  "物价参考票价是开局票价按物价折算到今年的价格。跟着物价调价时客流下降有限；超过参考票价越多，乘客流失越快，超过约 1.3 倍后多收的钱抵不上流失的客流。调价影响指满意度下降，持续 6 个月，涨幅超过物价越多越重。票价负担上限 −9 分，平均票价不超过时间价值的 35% 时没有负担。按里程计费时长途乘客付得更多。": "The inflation reference fare is the starting fare adjusted to this year's prices. Matching inflation has a limited effect on ridership; larger increases lose riders faster. Above about 1.3 times the reference, extra fares no longer offset the lost riders. Satisfaction penalties last 6 months and grow with the increase above inflation. The fare-burden penalty is capped at −9 points; there is no burden when the average fare is at most 35% of the value of time. Distance fares charge longer trips more.",
