  "伦敦大轰炸毁掉成片街区、人口骤减、拨款锐减，战后重建要花几十年": "The Blitz destroys whole districts, the population falls sharply and grants collapse; rebuilding takes decades",
  "伦敦大轰炸": "The Blitz",
  "伦敦大轰炸（1940–1941）": "The Blitz (1940–1941)",
  "史实：1939 年 9 月儿童疏散；1940 年 9 月起德军连续空袭伦敦（伦敦大轰炸），东区与码头区损失最重，数十万人夜宿地铁站台；地铁扩建计划搁置。估算：人口大幅减少，建设几乎停止，上学、购物与休闲出行骤减，汽油配给让汽车几乎退出街道。": "Historical: children were evacuated in September 1939; from September 1940 the Blitz bombed the city night after night, with the East End and the docks worst hit, and hundreds of thousands sheltered on Tube platforms; extension plans were shelved. Estimated: the population falls sharply, construction almost stops, school, shopping and leisure trips collapse, and petrol rationing all but clears cars from the streets.",
  "地铁通车年份（只作史实背景）、地标落成年份、主要道路通车年份、码头关闭年份、两次世界大战与伦敦大轰炸、拥堵费、奥运会、货币十进制。": "Metro opening years (as historical background only), landmark opening years, road opening years, dock closure years, the two world wars and the Blitz, the congestion charge, the Olympics, and decimalisation.",
